class MyHashMap {
    int size = 769;
    vector<list<pair<int, int>>> buckets;
public:
    MyHashMap() : buckets(769) {}

    void put(int key, int value) {
        int h = key % size;
        for (auto& pair : buckets[h]) {
            if (pair.first == key) {
                pair.second = value;
                return;
            }
        }
        buckets[h].push_back({key, value});
    }

    int get(int key) {
        int h = key % size;
        for (auto& pair : buckets[h]) {
            if (pair.first == key) return pair.second;
        }
        return -1;
    }

    void remove(int key) {
        int h = key % size;
        for (auto it = buckets[h].begin(); it != buckets[h].end(); ++it) {
            if (it->first == key) {
                buckets[h].erase(it);
                return;
            }
        }
    }
};

class MyHashMap {
    class Entry {
        int key, val;
        Entry(int k, int v) { key = k; val = v; }
    }
    private int size = 769;
    private LinkedList<Entry>[] buckets;

    public MyHashMap() {
        buckets = new LinkedList[size];
        for (int i = 0; i < size; i++) {
            buckets[i] = new LinkedList<>();
        }
    }

    public void put(int key, int value) {
        int h = key % size;
        for (Entry e : buckets[h]) {
            if (e.key == key) {
                e.val = value;
                return;
            }
        }
        buckets[h].add(new Entry(key, value));
    }

    public int get(int key) {
        int h = key % size;
        for (Entry e : buckets[h]) {
            if (e.key == key) return e.val;
        }
        return -1;
    }

    public void remove(int key) {
        int h = key % size;
        Entry toRemove = null;
        for (Entry e : buckets[h]) {
            if (e.key == key) {
                toRemove = e;
                break;
            }
        }
        if (toRemove != null) {
            buckets[h].remove(toRemove);
        }
    }
}

var MyHashMap = function() {
    this.size = 769;
    this.buckets = Array.from({ length: 769 }, () => []);
};

/** 
 * @param {number} key 
 * @param {number} value
 * @return {void}
 */
MyHashMap.prototype.put = function(key, value) {
    const h = key % this.size;
    for (const pair of this.buckets[h]) {
        if (pair[0] === key) {
            pair[1] = value;
            return;
        }
    }
    this.buckets[h].push([key, value]);
};

/** 
 * @param {number} key
 * @return {number}
 */
MyHashMap.prototype.get = function(key) {
    const h = key % this.size;
    for (const pair of this.buckets[h]) {
        if (pair[0] === key) return pair[1];
    }
    return -1;
};

/** 
 * @param {number} key
 * @return {void}
 */
MyHashMap.prototype.remove = function(key) {
    const h = key % this.size;
    const idx = this.buckets[h].findIndex(pair => pair[0] === key);
    if (idx !== -1) {
        this.buckets[h].splice(idx, 1);
    }
};
